	private static int zzUnpackAction(String packed, int offset, int[] result) {
		int i = 0;
		int j = offset;
		int l = packed.length();

		while (i < l) {
			int count = packed.charAt(i++);
			char value = packed.charAt(i++);

			while (true) {
				result[j++] = value;
				--count;
				if (count <= 0) {
					break;
				}
			}
		}

		return j;
	}
	
